def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    encrypted_chars = []

    for char in s:
        if char.isalpha():
            is_upper = char.isupper()
            base_index = ord('A') if is_upper else ord('a')

            # Calculate the new index with rotation of 2 * 2 = 4 positions down
            original_pos = alphabet.index(char.lower())
            shifted_pos = (original_pos + 4) % 26

            encrypted_char = chr(base_index + shifted_pos)
        else:
            encrypted_char = char

        encrypted_chars.append(encrypted_char)

    return ''.join(encrypted_chars)

